def shift_ascii(text, step):
    result = ''
    for char in text:
        if 'A' <= char <= 'Z':
            char = chr((ord(char) - ord('A') + step) % 26 + ord('A'))
        elif 'a' <= char <= 'z':
            char = chr((ord(char) - ord('a') + step) % 26 + ord('a'))
        result += char
    return [result, len(result), len(result.encode('utf-8'))]
